function* countdown(n: number): Generator<number, void, unknown> {
  for (let s = n; s > 0; s--) yield s;          // coalgebra
}

const mul = (acc: bigint, v: number): bigint => acc * BigInt(v);  // algebra

function factorial(n: number): bigint {
  let acc = 1n;
  for (const v of countdown(n)) acc = mul(acc, v);   // fused, no array
  return acc;
}
